# Rigid frame tree. Everything is measured from `origin`: the farthest-port screw on the front of the
# camera cage, which is also the CAD model origin (riptide_descriptions talos.yaml uses the same datum).
# `com` is the physics body; when the center of mass moves, edit its transform. The `body` centers stay
# relative to the center of mass.
frames:
  root: origin
  body: com
  transforms:
  - {parent: origin, child: base_link, position_m: [-0.14, 0.03, -0.09], orientation_wxyz: [1, 0, 0, 0]}
  - {parent: origin, child: com, position_m: [-0.150, 0.041, -0.016], orientation_wxyz: [1, 0, 0, 0]}   # measured wet, everything on
  - {parent: origin, child: thruster_VUS, position_m: [-0.134, -0.369, 0.242], orientation_wxyz: [1.0, 0.0, 0.0, 0.0]}
  - {parent: origin, child: thruster_VUP, position_m: [-0.134, 0.438, 0.242], orientation_wxyz: [1.0, 0.0, 0.0, 0.0]}
  - {parent: origin, child: thruster_HUS, position_m: [-0.14, -0.26, 0.141], orientation_wxyz: [0.6532688037723191, 0.2704955304628238, -0.27044044338085915, 0.6534018706749187]}
