# Thruster order is the actuator index; the bridge maps ROS array order separately.
# Each acts at its `thruster_*` frame, along that frame's +X.
thrusters:
# All eight share riptide_mpc models/talos.yaml's thruster model: delay 0.03 s, rise 0.08 s, fall 0.06 s,
# slew 300 N/s, +/-24 N, deadband 0, scales 1, efficiency 1, propeller radius 0.05 m.
- {id: VUS, type: lagged_force, frame: thruster_VUS, parameters: {delay_s: 0.03, rise_time_s: 0.08, fall_time_s: 0.06, slew_rate_n_s: 300.0, forward_limit_n: 24.0, reverse_limit_n: 24.0, deadband_n: 0.0, forward_scale: 1.0, reverse_scale: 1.0, efficiency: 1.0, propeller_radius_m: 0.05}}
