- {id: HUP, type: lagged_force, frame: thruster_HUP, parameters: {delay_s: 0.03, rise_time_s: 0.08, fall_time_s: 0.06, slew_rate_n_s: 300.0, forward_limit_n: 24.0, reverse_limit_n: 24.0, deadband_n: 0.0, forward_scale: 1.0, reverse_scale: 1.0, efficiency: 1.0, propeller_radius_m: 0.05}}
- {id: HLS, type: lagged_force, frame: thruster_HLS, parameters: {delay_s: 0.03, rise_time_s: 0.08, fall_time_s: 0.06, slew_rate_n_s: 300.0, forward_limit_n: 24.0, reverse_limit_n: 24.0, deadband_n: 0.0, forward_scale: 1.0, reverse_scale: 1.0, efficiency: 1.0, propeller_radius_m: 0.05}}
- {id: HLP, type: lagged_force, frame: thruster_HLP, parameters: {delay_s: 0.03, rise_time_s: 0.08, fall_time_s: 0.06, slew_rate_n_s: 300.0, forward_limit_n: 24.0, reverse_limit_n: 24.0, deadband_n: 0.0, forward_scale: 1.0, reverse_scale: 1.0, efficiency: 1.0, propeller_radius_m: 0.05}}
- {id: VLS, type: lagged_force, frame: thruster_VLS, parameters: {delay_s: 0.03, rise_time_s: 0.08, fall_time_s: 0.06, slew_rate_n_s: 300.0, forward_limit_n: 24.0, reverse_limit_n: 24.0, deadband_n: 0.0, forward_scale: 1.0, reverse_scale: 1.0, efficiency: 1.0, propeller_radius_m: 0.05}}
