# White lines on a dark blue bottom; positions fitted to the pool video.
markings:
  color_rgb: [0.85, 0.93, 0.95]
  width_m: 0.254
  # Eight lap lines centered in 7 ft lanes (first 3.5 ft from the y = 0 wall), T ends 1.63 m off the end walls.
  lane_grid:
    along_x: {count: 8, spacing_m: 2.1336}
    inset_m: 1.63
    ends: t
    t_length_m: 1.04
    # A dark plus target above each lap line on both end walls: a stem from the waterline down to 0.97 m and a
    # 0.91 m crossbar at 0.46 m, 0.3 m strokes (fitted on the shallow-end wall).
    targets: {stem_m: [-0.965, 0.0], bar_z_m: -0.46, bar_length_m: 0.91, width_m: 0.3, color_rgb: [0.05, 0.12, 0.16]}
  lines:
  # The dive stations' lines off the platform (y = 0) wall: 14 ft + 12.5 ft apart from the deep wall, 20 ft long.
  - {from: [4.2672, 2.031], to: [4.2672, 8.127]}
  - {from: [8.0772, 2.568], to: [8.0772, 8.664]}
  - {from: [11.8872, 3.148], to: [11.8872, 9.244]}
  - {from: [15.6972, 1.806], to: [15.6972, 8.057]}
  # Diving lines beside lap lines 4 and 6 at the shallow end.
  - {from: [19.83, 7.936], to: [23.6, 7.936]}
  - {from: [18.02, 10.988], to: [23.52, 10.988]}
  wall_lines:
  # A dark band around the walls about 1.2 m down.
  - {wall: x_min, from: [0, -1.18], to: [17.0688, -1.18], width_m: 0.1, color_rgb: [0.05, 0.12, 0.16]}
  - {wall: x_max, from: [0, -1.18], to: [17.0688, -1.18], width_m: 0.1, color_rgb: [0.05, 0.12, 0.16]}

# Raised and recessed fittings. The meshes are built by assets/make_meshes.py (edit and re-run it to change them).
