# Operator scorecard in the viewer.
ui:
  title: RoboSub 2026 scorecard
  run_options:
  - key: role
    label: Coin-flip role
    type: choice
    default: repair
    choices:
    - {value: repair, label: Survey & Repair}
    - {value: rescue, label: Search & Rescue}
  - {key: heading_coin, label: Heading coin flip, type: bool, default: true}
  - {key: role_coin, label: Role coin flip, type: bool, default: true}
  focus: [Course, Vehicle, gate, torpedo, slalom, bins, table, Payloads, Claw]
  demo_targets: [gate, torpedo, bins, table]
