tf:
  publish:
  - {parent: world, child: simulator/talos/base_link, native: 'state:robot.reference_pose', rate_hz: 100}   # truth
  # The navigation stack owns the camera links; the bridge adds their optical frames.
  static:
  - {parent: talos/ffc_camera_link, child: talos/ffc_left_camera_optical_frame, from_frame: ffc_mount, to_frame: ffc_left_optical}
  - {parent: talos/ffc_left_camera_optical_frame, child: talos/ffc_right_camera_optical_frame, from_frame: ffc_left_optical, to_frame: ffc_right_optical}
  - {parent: talos/dfc_camera_link, child: talos/dfc_left_camera_optical_frame, from_frame: dfc_mount, to_frame: dfc_left_optical}
  - {parent: talos/dfc_left_camera_optical_frame, child: talos/dfc_right_camera_optical_frame, from_frame: dfc_left_optical, to_frame: dfc_right_optical}
  # Simulator-truth tree under the published truth base; mirrors the robot pack so tools can
  # compare truth with the estimate.
  - {parent: simulator/talos/base_link, child: simulator/talos/origin, from_frame: base_link, to_frame: origin, truth: true}
  - {parent: simulator/talos/base_link, child: simulator/talos/ffc_camera_link, from_frame: base_link, to_frame: ffc_mount, truth: true}
  - {parent: simulator/talos/ffc_camera_link, child: simulator/talos/ffc_left_camera_optical_frame, from_frame: ffc_mount, to_frame: ffc_left_optical, truth: true}
  - {parent: simulator/talos/base_link, child: simulator/talos/dfc_camera_link, from_frame: base_link, to_frame: dfc_mount, truth: true}
  - {parent: simulator/talos/dfc_camera_link, child: simulator/talos/dfc_left_camera_optical_frame, from_frame: dfc_mount, to_frame: dfc_left_optical, truth: true}
  # Transforms the bridge only reads; their owners are external and the bridge never republishes them.
  lookup:
  - {parent: world, child: map}    # riptide_mapping2 world_to_map (identity start; XY/yaw free)
  - {parent: world, child: odom}   # riptide_hardware2 navigation.launch.py static world->odom
  never_publish: [talos/base_link, talos/imu_link, talos/fog_link, talos/dvl_link,
                  talos/ffc_camera_link, talos/dfc_camera_link, world, odom, map]

services:
